// loom/rom.h — ROM: the read-only memory shipped with the program, mounted first
// (GRAF_HUB_KOD_SILNIK_2026-10-13 sections 2-3).
//
// The ROM's content is DATA: the catalogue pack data/graph/rom.pack (generated by tools/gen_rom_catalogue.py)
// embedded in the builtin graph_entry runtime profile under /rom. Its 13 items name the program files and
// data packs that implement each part, with sha256, or say "missing". Mechanism here:
//   Rom           read-only view; every write/remove is refused with a stated reason.
//   MountRegistry ordered memories; the ROM is always first and cannot be unmounted, reordered or written.
// A user "overrides" a ROM item with a copy in the writable memory: a graph_entry profile overlay
// (<data_dir>/profiles/graph_entry.pack, overrides.rom.items.<id>), the existing preset/overlay mechanism.
// Addresses are "rom:<item id>".
#pragma once

#include <filesystem>
#include <string>
#include <string_view>
#include <vector>

#include "loom/result.h"
#include "loom/util/json.h"

namespace loom::rom {

inline constexpr std::string_view kMountName = "rom";
inline constexpr std::string_view kAddressPrefix = "rom:";

class Rom {
 public:
  // Builtin catalogue; fails only if the embedded profile lacks /rom.
  static Result<Rom> open();

  const Json& catalogue() const noexcept { return items_; }   // {id: item}
  std::vector<std::string> ids() const;                       // by section-3 number
  Result<Json> read(std::string_view address) const;          // "rom:<id>" or bare id
  // Counts by status: {"present":n,"partial":n,"missing":n}.
  Json status_counts() const;

  // The ROM is never written. Each returns Errc::Unsupported with reason "rom_read_only: ...".
  Status write(std::string_view address, const Json& value) const;
  Status remove(std::string_view address) const;

 private:
  Json items_ = Json::object();
};

struct Mount {
  std::string name;
  bool writable = false;
  std::filesystem::path data_dir;  // writable memory location (overlay home)
};

class MountRegistry {
 public:
  // [rom (read-only), user (writable, data_dir)].
  static MountRegistry standard(const std::filesystem::path& data_dir);

  // Appended after the ROM and the mounts already present; the name "rom" is reserved.
  Status add(Mount mount);
  const std::vector<Mount>& mounts() const noexcept { return mounts_; }  // mounts()[0] is always the ROM

  // Layered read: the ROM item, then the writable mounts' overlays in mount order (later wins).
  // -> {"address","source":"rom"|"overlay","item":{...},"rom_item":{...}}
  Result<Json> read(std::string_view address) const;
  // Write into a named mount. "rom" -> refused. A writable mount stores a patch as an overlay of the item.
  Status write(std::string_view mount, std::string_view address, const Json& patch) const;
  Status remove(std::string_view mount, std::string_view address) const;

 private:
  std::vector<Mount> mounts_;
};

}  // namespace loom::rom
